// Auto-generated bundled runtime LUT binaries for offline pro-camera analog emulation.
import { Buffer } from '@craftzdog/react-native-buffer'

const BALI_400_BASE64 =
  ''
const MARTHA_BASE64 =
  ''

const AURA_400_BASE64 =
  ""

const AMBER_200_BASE64 =
  ""

const SILVER_400_BASE64 =
  ""

const NEON_800T_BASE64 =
  ""

export function getBundledLutBytes(id: string): Uint8Array | null {
  if (id === 'bali-400-v1') {
    return new Uint8Array(Buffer.from(BALI_400_BASE64, 'base64'))
  }
  if (id === 'martha-v1') {
    return new Uint8Array(Buffer.from(MARTHA_BASE64, 'base64'))
  }
  if (id === 'momints-aura-400') {
    return new Uint8Array(Buffer.from(AURA_400_BASE64, 'base64'))
  }
  if (id === 'momints-amber-200') {
    return new Uint8Array(Buffer.from(AMBER_200_BASE64, 'base64'))
  }
  if (id === 'momints-silver-400') {
    return new Uint8Array(Buffer.from(SILVER_400_BASE64, 'base64'))
  }
  if (id === 'momints-neon-800t') {
    return new Uint8Array(Buffer.from(NEON_800T_BASE64, 'base64'))
  }
  return null
}
